CREATE DATABASE IF NOT EXISTS insight_mcsitobes CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE insight_mcsitobes;

CREATE TABLE IF NOT EXISTS companies (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,legal_name VARCHAR(220),company_type VARCHAR(80) NOT NULL DEFAULT 'Subsidiary',industry VARCHAR(140),is_parent TINYINT(1) DEFAULT 0,parent_company_id INT NULL,sanleo_share DECIMAL(5,2) DEFAULT 0,country VARCHAR(80) DEFAULT 'India',currency CHAR(3) DEFAULT 'INR',registration_no VARCHAR(100),website VARCHAR(180),logo_storage_key VARCHAR(500),status VARCHAR(30) DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(parent_company_id) REFERENCES companies(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS company_shareholders (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,shareholder_name VARCHAR(180) NOT NULL,shareholder_type VARCHAR(60) DEFAULT 'Individual',share_percent DECIMAL(5,2) NOT NULL,effective_from DATE NULL,effective_to DATE NULL,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(140) NOT NULL,email VARCHAR(180) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(50) DEFAULT 'viewer',status VARCHAR(30) DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_company_access (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,company_id INT NOT NULL,access_role VARCHAR(50) DEFAULT 'viewer',UNIQUE KEY uq_access(user_id,company_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS people (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,position VARCHAR(120),primary_company_id INT NULL,phone VARCHAR(60),email VARCHAR(180),notes TEXT,FOREIGN KEY(primary_company_id) REFERENCES companies(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS products (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,name VARCHAR(180) NOT NULL,category VARCHAR(100),description TEXT,status VARCHAR(30) DEFAULT 'Active',website VARCHAR(180),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS finance_transactions (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,date DATE NOT NULL,type ENUM('income','expense','capital','loan','intercompany') NOT NULL,category VARCHAR(100),description VARCHAR(255),amount DECIMAL(15,2) NOT NULL,currency CHAR(3) DEFAULT 'INR',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS bank_accounts (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,bank_name VARCHAR(140),account_name VARCHAR(180),account_number VARCHAR(100),iban VARCHAR(100),swift VARCHAR(50),branch VARCHAR(180),currency CHAR(3) DEFAULT 'INR',status VARCHAR(30) DEFAULT 'Active',FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reminders (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NULL,title VARCHAR(220) NOT NULL,category VARCHAR(80),due_date DATE NOT NULL,priority VARCHAR(20) DEFAULT 'Medium',status VARCHAR(30) DEFAULT 'pending',recurrence VARCHAR(60),notes TEXT,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS offices (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,name VARCHAR(180),city VARCHAR(120),address TEXT,landlord VARCHAR(180),monthly_rent DECIMAL(15,2) DEFAULT 0,rent_due_day INT,lease_start DATE,lease_end DATE,security_deposit DECIMAL(15,2) DEFAULT 0,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS employees (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,employee_code VARCHAR(40),name VARCHAR(160) NOT NULL,designation VARCHAR(120),joining_date DATE,salary DECIMAL(15,2) DEFAULT 0,phone VARCHAR(60),email VARCHAR(180),status VARCHAR(30) DEFAULT 'Active',FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS payroll (id INT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,month CHAR(7) NOT NULL,gross_salary DECIMAL(15,2) DEFAULT 0,deduction DECIMAL(15,2) DEFAULT 0,net_salary DECIMAL(15,2) DEFAULT 0,status VARCHAR(30) DEFAULT 'Pending',paid_date DATE,UNIQUE KEY uq_payroll(employee_id,month),FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS assets (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,asset_code VARCHAR(60),name VARCHAR(180),category VARCHAR(100),assigned_to VARCHAR(180),purchase_date DATE,purchase_cost DECIMAL(15,2),warranty_expiry DATE,status VARCHAR(30) DEFAULT 'Available',FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS domains (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,domain VARCHAR(180) NOT NULL,registrar VARCHAR(120),expiry_date DATE,auto_renew TINYINT(1) DEFAULT 0,status VARCHAR(30) DEFAULT 'Active',FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS email_accounts (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,email VARCHAR(180) NOT NULL,provider VARCHAR(100),assigned_to VARCHAR(180),status VARCHAR(30) DEFAULT 'Active',FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS social_accounts (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,platform VARCHAR(80),username VARCHAR(180),url VARCHAR(255),manager VARCHAR(180),status VARCHAR(30) DEFAULT 'Active',FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS credentials (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,service_name VARCHAR(180),username VARCHAR(180),encrypted_secret TEXT,url VARCHAR(255),twofa_owner VARCHAR(180),recovery_info TEXT,notes TEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS documents (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,name VARCHAR(220),category VARCHAR(100),storage_key VARCHAR(255),expiry_date DATE,confidential TINYINT(1) DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(120),entity_type VARCHAR(100),entity_name VARCHAR(220),ip_address VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS finance_investors (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,investor_name VARCHAR(180) NOT NULL,phone VARCHAR(40),email VARCHAR(180),id_number VARCHAR(100),investment_amount DECIMAL(15,2) NOT NULL,interest_rate DECIMAL(8,4) NOT NULL,interest_type ENUM('flat_amount','percentage') NOT NULL DEFAULT 'percentage',monthly_interest_amount DECIMAL(15,2) NOT NULL,investment_date DATE NOT NULL,next_interest_date DATE NOT NULL,payment_method VARCHAR(60) DEFAULT 'Bank transfer',reference_no VARCHAR(100),status ENUM('active','closed') NOT NULL DEFAULT 'active',notes TEXT,created_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY ix_finance_investor_due(company_id,status,next_interest_date),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS finance_investor_interest_payments (id INT AUTO_INCREMENT PRIMARY KEY,investor_id INT NOT NULL,receipt_number VARCHAR(100) NOT NULL UNIQUE,amount DECIMAL(15,2) NOT NULL,payment_date DATE NOT NULL,interest_for_date DATE NOT NULL,periods_count INT NOT NULL DEFAULT 1,payment_method VARCHAR(60) NOT NULL DEFAULT 'Bank transfer',reference_no VARCHAR(100),notes TEXT,paid_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY ix_investor_interest_payment(investor_id,payment_date),FOREIGN KEY(investor_id) REFERENCES finance_investors(id) ON DELETE CASCADE,FOREIGN KEY(paid_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS program_registry (id INT AUTO_INCREMENT PRIMARY KEY,program_name VARCHAR(180) NOT NULL,environment VARCHAR(40) NOT NULL DEFAULT 'production',status VARCHAR(30) NOT NULL DEFAULT 'active',public_url VARCHAR(500),git_url VARCHAR(500),git_branch VARCHAR(120),server_host VARCHAR(255),ssh_user VARCHAR(120),ssh_port INT NOT NULL DEFAULT 22,deployment_path VARCHAR(500),process_manager VARCHAR(180),encrypted_pem LONGTEXT,encrypted_env LONGTEXT,notes TEXT,created_by INT NULL,updated_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_program_environment(program_name,environment),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL);
